// exchange to a core that won't accept the JWT.
func exchangeOpsToken(ctx context.Context, cfg Config, coreURL, loginJWT string) (string, error) {
	coreURL = strings.TrimRight(coreURL, "/")
	if coreURL == "" {
		return "", errors.New("no entire-core URL configured for admin commands; log in with `entire-core auth login` or set ENTIRE_CORE_BASE_URL")
	}
	sharedOpsAuthMu.Lock()
	key := coreURL + "|" + loginJWT
	if sharedOpsAuth == nil || sharedOpsAuthKey != key {
		sharedOpsAuth = newOpsAuth(coreURL, loginJWT, newHTTPClient(cfg.SkipTLSVerify))
		sharedOpsAuthKey = key
	}
	auth := sharedOpsAuth
	sharedOpsAuthMu.Unlock()
	return auth.get(ctx)
}

