package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

// opsAuth exchanges a login JWT for a short-lived ops-access JWT via
// core's RFC 8693 STS endpoint (POST /api/authz/sts/token,
// requested_token_type=urn:entire:token-type:ops-access). Ops tokens
// carry platform-admin authority and are required for any
// `entiredb admin ...` RPC. Parallels cmd/git-remote-entire/scoped_auth.go.
type opsAuth struct {
	coreURL    string // trimmed, no trailing slash
	loginJWT   string
	httpClient *http.Client

	mu     sync.Mutex
	cached opsTokenEntry
}

type opsTokenEntry struct {
	token     string
	expiresAt time.Time
}

// opsTokenSafetyMargin is subtracted from the server's expires_in so the
// client rotates before actual expiry — covers clock skew and gives slow
// RPCs a fresh token.
const opsTokenSafetyMargin = time.Minute

func newOpsAuth(coreURL, loginJWT string, httpClient *http.Client) *opsAuth {
	return &opsAuth{
		coreURL:    strings.TrimRight(coreURL, "/"),
		loginJWT:   loginJWT,
		httpClient: httpClient,
	}
}

// get returns a valid ops-access token, exchanging against core if the
// cached entry is missing or past its safety margin.
func (o *opsAuth) get(ctx context.Context) (string, error) {
	o.mu.Lock()
	defer o.mu.Unlock()

	if o.cached.token != "" && time.Now().Before(o.cached.expiresAt) {
		return o.cached.token, nil
	}

	form := url.Values{}
	form.Set("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange")
	form.Set("subject_token_type", "urn:ietf:params:oauth:token-type:jwt")
	form.Set("subject_token", o.loginJWT)
	form.Set("requested_token_type", "urn:entire:token-type:ops-access")

	req, err := http.NewRequestWithContext(ctx, http.MethodPost,
		o.coreURL+"/api/authz/sts/token", strings.NewReader(form.Encode()))
	if err != nil {
		return "", fmt.Errorf("build ops-token request: %w", err)
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	resp, err := o.httpClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("ops-token exchange: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		msg, _ := io.ReadAll(io.LimitReader(resp.Body, 1024)) //nolint:errcheck // best-effort body read for error message
		if resp.StatusCode == http.StatusForbidden {
			return "", errors.New("ops-token denied: you are not a platform admin")
		}
		return "", fmt.Errorf("ops-token exchange failed: HTTP %d: %s",
			resp.StatusCode, strings.TrimSpace(string(msg)))
	}

	var out struct {
		AccessToken string `json:"access_token"`
		ExpiresIn   int    `json:"expires_in"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", fmt.Errorf("decode ops-token response: %w", err)
	}
	if out.AccessToken == "" {
		return "", errors.New("ops-token response missing access_token")
	}

	ttl := time.Duration(out.ExpiresIn) * time.Second
	if ttl <= opsTokenSafetyMargin {
		// Effectively already in the stale window — hand it out for this
		// request but don't cache it, or the next call would see
		// expiresAt in the past and re-exchange synchronously.
		return out.AccessToken, nil
	}
	o.cached = opsTokenEntry{token: out.AccessToken, expiresAt: time.Now().Add(ttl - opsTokenSafetyMargin)}
	return out.AccessToken, nil
}

// exchangeRepoScopedToken swaps a login JWT for a short-lived repo-scoped
// JWT at core's RFC 8693 STS endpoint. Used by CLI git operations (clone,
// etc.) that talk HTTPS directly — git-remote-entire has its own copy for
// the entire:// transport. coreURL is the JWT's issuer (resolved from
// the active context); never read from cfg.EntireCoreBaseURL directly,
// so cross-region setups don't post EU-issued JWTs at a US core.
//
// clusterHost is the data-plane host the user typed (the positional on
// `entiredb mirror`, or the parsed URL host on `entiredb repo clone`).
// Mirror lookups require it to disambiguate same-upstream mirrors
// across regions; sending the wrong one earns a 400 "unknown
// cluster_host" from core. Empty string skips the form field — the
// owner/repo path tolerates that.
func exchangeRepoScopedToken(ctx context.Context, coreURL, loginJWT, repoPath, action, clusterHost string, httpClient *http.Client) (string, error) {
	coreURL = strings.TrimRight(coreURL, "/")
	if coreURL == "" {
		return "", errors.New("no entire-core URL configured for scoped-token exchange; log in with `entire-core auth login` or set ENTIRE_CORE_BASE_URL")
	}

	form := url.Values{}
	form.Set("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange")
	form.Set("subject_token_type", "urn:ietf:params:oauth:token-type:jwt")
	form.Set("subject_token", loginJWT)
	form.Set("requested_token_type", "urn:entire:token-type:repo-access")
	form.Set("resource", repoPath)
	form.Set("scope", "repo:"+action)
	if clusterHost != "" {
		form.Set("cluster_host", clusterHost)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodPost,
		coreURL+"/api/authz/sts/token", strings.NewReader(form.Encode()))
	if err != nil {
		return "", fmt.Errorf("build repo-token request: %w", err)
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	resp, err := httpClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("repo-token exchange: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		msg, _ := io.ReadAll(io.LimitReader(resp.Body, 1024)) //nolint:errcheck // best-effort error body
		return "", fmt.Errorf("repo-token exchange failed: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(msg)))
	}

	var out struct {
		AccessToken string `json:"access_token"`
		ExpiresIn   int    `json:"expires_in"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", fmt.Errorf("decode repo-token response: %w", err)
	}
	if out.AccessToken == "" {
		return "", errors.New("repo-token response missing access_token")
	}
	return out.AccessToken, nil
}

